contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address receiver) public payable {
        require(amount == 0 || receiver != address(0), "trivial precondition");

        uint256 beforeCurrentRound = c.currentRound();
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        uint256 beforeUserUsdc = c.usdcBalance(receiver);
        uint256 beforeUnclaimedShares = c.unclaimedShares(receiver);

        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.currentRound() == beforeCurrentRound);
            assert(c.roundUsdcBalance() == beforeRoundUsdc);
            assert(c.usdcBalance(receiver) == beforeUserUsdc);
            assert(c.unclaimedShares(receiver) == beforeUnclaimedShares);
        } else {
            assert(c.currentRound() == beforeCurrentRound);
            assert(c.roundUsdcBalance() == beforeRoundUsdc + amount);
            assert(c.usdcBalance(receiver) == beforeUserUsdc + amount);
            assert(c.unclaimedShares(receiver) == beforeUnclaimedShares);
        }
    }

    receive() external payable {}
}

