contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address user,
        uint256 amount,
        address receiver,
        uint256 claimAmount
    ) public payable {
        require(user != address(0), "user zero");
        require(receiver != address(0), "receiver zero");

        uint256 beforeShares = c.unclaimedShares(user);

        // Make a USDC deposit into the batching manager. The call may revert for
        // arbitrary inputs, so execute it with low-level call and gate the final
        // assertion on success + observable effects.
        (bool okDeposit, ) = address(c).call(
            abi.encodeWithSignature("depositUsdc(uint256,address)", amount, user)
        );

        if (okDeposit) {
            // The contract function should never record unclaimed shares before a round
            // is executed; unclaimedShares() must not decrease as a result of a deposit.
            uint256 afterShares = c.unclaimedShares(user);
            assert(afterShares >= beforeShares);
        } else {
            // If the deposit reverts, the call must not have changed the user's
            // unclaimed shares.
            uint256 afterShares = c.unclaimedShares(user);
            assert(afterShares == beforeShares);
        }
    }
}

